<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('clinical.view');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$sql="SELECT r.*,p.name patient_name,u.name professional_name FROM clinical_records r JOIN patients p ON p.id=r.patient_id AND p.tenant_id=r.tenant_id JOIN users u ON u.id=r.professional_id AND u.tenant_id=r.tenant_id WHERE r.tenant_id=:t";$params=['t'=>$user['tenant_id']];if($user['role_slug']==='supervised'){$sql.=' AND r.professional_id=:u';$params['u']=$user['id'];}elseif($user['role_slug']==='psychologist'){$sql.=' AND (r.professional_id=:professional_id OR r.supervisor_id=:supervisor_id)';$params['professional_id']=$user['id'];$params['supervisor_id']=$user['id'];}elseif($user['role_slug']==='clinic_admin'){$sql.=' AND (r.professional_id=:professional_id OR r.supervisor_id=:supervisor_id)';$params['professional_id']=$user['id'];$params['supervisor_id']=$user['id'];}$sql.=' ORDER BY r.created_at DESC LIMIT 150';$st=db()->prepare($sql);$st->execute($params);$records=$st->fetchAll();layout('Prontuário',function()use($records,$user){?><div class="page-head"><div><span class="eyebrow">Prática clínica</span><h1>Prontuário eletrônico</h1><p>Evoluções criptografadas, segregadas por profissional e com trilha de aprovação.</p></div><?php if(\App\Core\Rbac::allows((int)$user['id'],'clinical.write')):?><a class="button" href="<?=e(url('clinical/new.php'))?>">+ Nova evolução</a><?php endif?></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Paciente</th><th>Tipo</th><th>Profissional</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="6" class="muted">Nenhum registro clínico acessível ao seu perfil.</td></tr><?php endif?><?php foreach($records as $r):?><tr><td><?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?></td><td data-private><?=e($r['patient_name'])?></td><td><?=e(strtoupper($r['record_type']))?></td><td><?=e($r['professional_name'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a href="<?=e(url('clinical/view.php?id='.$r['id']))?>">Abrir</a></td></tr><?php endforeach?></tbody></table></div></div><?php },['active'=>'clinical']);
